import java.util.*;
import java.io.*;

public class HeightAllTheSame {
    private static final long MOD = 998244353L;

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer tokenizer = new StringTokenizer(reader.readLine());
        long N = Long.parseLong(tokenizer.nextToken());
        long M = Long.parseLong(tokenizer.nextToken());
        long L = Long.parseLong(tokenizer.nextToken());
        long R = Long.parseLong(tokenizer.nextToken());

        long squares = N * M;
        long number = R - L + 1;
        long computed = exp(number, squares);
        long inv2 = (MOD + 1) / 2;
        long answer;

        if (squares % 2 == 1) {
            answer = computed;
        } else if (number % 2 == 0) {
            answer = computed * inv2 % MOD;
        } else {
            answer = (computed + 1) * inv2 % MOD;
        }

        PrintWriter out = new PrintWriter(System.out);
        out.println(answer);
        reader.close();
        out.close();
    }

    private static long exp(long base, long e) {
        if (e <= 0L) {
            return 1L;
        }
        if (e == 1L) {
            return base % MOD;
        }
        long half = exp(base, e / 2L);
        half = half * half % MOD;
        if ((e & 1L) == 1L) {
            half = half * base % MOD;
        }
        return half;
    }
}
